const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry - Central Valley of California
  const centralValley = ee.Geometry.Polygon([
    [-122.5, 40.0], [-121.0, 40.0], [-119.0, 36.0], [-121.0, 35.0], [-122.5, 37.0]
  ]);

  // 2. Data Acquisition - GRACE/GRACE-FO for water equivalent thickness
  const oct2022 = ee.ImageCollection('NASA/GRACE/MASS_GRIDS/LAND')
    .filterDate('2022-10-01', '2022-10-31')
    .select('lwe_thickness');

  const mar2023 = ee.ImageCollection('NASA/GRACE/MASS_GRIDS/LAND')
    .filterDate('2023-03-01', '2023-03-31')
    .select('lwe_thickness');

  // Check collection sizes
  const octSize = oct2022.size().getInfo();
  const marSize = mar2023.size().getInfo();

  console.log(`Oct 2022 Images: ${octSize}, Mar 2023 Images: ${marSize}`);

  if (octSize === 0 || marSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get first image from each collection
  const octImg = oct2022.first();
  const marImg = mar2023.first();

  // 3. Processing - Calculate mean water equivalent thickness
  const octStats = octImg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: centralValley,
    scale: 100000,
    maxPixels: 1e9
  });

  const marStats = marImg.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: centralValley,
    scale: 100000,
    maxPixels: 1e9
  });

  const octValue = octStats.get('lwe_thickness').getInfo();
  const marValue = marStats.get('lwe_thickness').getInfo();

  // Check pixel counts
  const octCount = octImg.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: centralValley,
    scale: 100000,
    maxPixels: 1e9
  }).get('lwe_thickness').getInfo();

  const marCount = marImg.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: centralValley,
    scale: 100000,
    maxPixels: 1e9
  }).get('lwe_thickness').getInfo();

  console.log(`Oct 2022 Pixels: ${octCount}, Value: ${octValue}`);
  console.log(`Mar 2023 Pixels: ${marCount}, Value: ${marValue}`);

  // 4. Validation & Final Answer
  if (octCount === 0 || marCount === 0) {
    console.log("<answer>C2</answer>");
  } else if (octValue === null || marValue === null || 
             isNaN(octValue) || isNaN(marValue)) {
    console.log("<answer>C3</answer>");
  } else if (octValue > marValue) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
